def judge(nums):
  if nums == []:
    return True
  ret = False
  m = nums[0]
  if nums.count(m) == 3:
    ret = ret or judge(nums[3:])
  if m in nums and m + 1 in nums and m + 2 in nums:
    new_nums = nums[:]
    new_nums.remove(m)
    new_nums.remove(m + 1)
    new_nums.remove(m + 2)
    ret = ret or judge(new_nums)
  return ret

