def dfs(v, t, f, used):
    """ 増加パスをDFSで探す、再帰バージョン
    Args:
        v (int): 探索の開始地点
        t (int): 探索の終了地点
        f (int): 流す量
        used (list): 訪れた点の記録
    Returns:
        int: 流すことのできた量
    """
    if v == t:
        return f
    used[v] = 1
    for idx, (nn, cap, rev) in enumerate(G[v]):
        if used[nn] == 0 and cap > 0:
            d = dfs(nn, t, min(f, cap), used)
            if d > 0:
                G[v][idx][1] -= d
                G[nn][rev][1] += d
                return d
    else:
        return 0

