def solve(N, edges):
    adj = Graph(N, edges, directed=True).adj
    parent = [-1]*N

    # find root
    deg = [0]*N
    for u,v in edges:
        deg[v] += 1

    root = next(v for v,d in enumerate(deg) if d==0)

    topo = [-1]*N
    stack = [root]
    for i in range(N):
        v = stack.pop()
        topo[i] = v
        for u in adj[v]:
            deg[u] -= 1
            if deg[u] == 0:
                stack.append(u)

    dist = [0]*N
    for v in topo:
        d = dist[v]
        for u in adj[v]:
            dist[u] = max2(dist[u], d+1)

    parent = [-1]*N
    for v,l in enumerate(adj):
        d = dist[v]+1
        for u in l:
            if d == dist[u]:
                parent[u] = v
    return (p+1 for p in parent)




